#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

REPO="zinpaing78072-collab/inventory-pwa"
TOTAL_STAGES=7

banner "Server phone setup (Termux)"

note "Keep the server phone: plugged in, on the home Wi-Fi, next to you while"
note "you run this wizard. You drive the phone; this wizard tells you exactly"
note "what to paste into Termux and checks the result from the Mac."

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Install Termux (F-Droid)"
say "Termux must come from F-Droid — the Play Store build is outdated and"
say "actually broken for our needs."
open_url "https://f-droid.org/en/packages/com.termux/"
step "On the F-Droid page, tap 'Download APK' and let it finish."
step "Tap the downloaded file; Chrome will ask to 'allow installing unknown apps' — allow it, then Install."
step "Open Termux once and leave it open."
say ""
say "Now tell Android to never put Termux to sleep (this is what keeps the"
say "shop server alive when the screen is off):"
step "Android Settings → Apps → Termux → Battery → Unrestricted."
say "(If your phone shows 'Optimize battery usage' instead: find Termux in that list and leave it UNCHECKED/optimized=false.)"
pause "Done — Termux installed and battery unrestricted?"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Termux packages"
say "Paste these two commands into Termux, one at a time. Long-press in the"
say "terminal → Paste."
step "pkg update -y && pkg install -y nodejs-lts git"
step "npm install -g pnpm pm2"
say ""
say "Then check all three work:"
step "node -v && pnpm -v && pm2 -v"
note "If a message about '(100%)APT already has the newest package' appears, that's fine."
note "If npm warns about updates, also fine — versions just need to exist."
pause "All three printed a version number?"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Clone the code"
step "Paste this into Termux:"
say ""
say "    cd ~ && git clone https://github.com/${REPO}.git"
say ""
if confirm "Did the clone succeed (no 'fatal: Authentication failed')?"; then
  step "Next paste:    cd ${REPO#*/}"
else
  say "The repo needs authentication, so we'll make a GitHub token."
  open_url "https://github.com/settings/personal-access-tokens/new"
  step "Fine-grained token: give it a name like 'termux-inventory'."
  step "Repository access → 'Only select repositories' → pick inventory-pwa."
  step "Permissions → Repository permissions → Contents: 'Read and write' (needed for update.sh git pull)."
  step "Click 'Generate token', copy the token (starts github_pat_), then paste it here."
  ask_secret GH_TOKEN "Paste the token here:"
  if [[ -z "$GH_TOKEN" ]]; then
    warn "No token captured. Re-run this wizard to finish stage 3 with a token."
  else
    say "Paste these two lines into Termux, one per line (the second one also"
    say "rewires git so future './update.sh' pulls keep working):"
    say ""
    say "    cd ~"
    say "    git clone https://zinpaing78072-collab:${GH_TOKEN}@github.com/${REPO}.git && cd ${REPO#*/} && git remote set-url origin https://zinpaing78072-collab:${GH_TOKEN}@github.com/${REPO}.git"
    say ""
    warn "Don't worry that the token is visible on this screen — it lives only in the phone's git config."
    pause "Clone succeeded and you're inside ~/inventory-pwa?"
  fi
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Install + build"
say "Still inside ~/inventory-pwa in Termux, paste:"
step "pnpm install && pnpm --filter @inv/server build && pnpm --filter @inv/web build"
warn "On a phone this takes 5–10 minutes. Keep the screen on and let it run."
pause "Both builds finished without an 'ERROR' or 'ELIFECYCLE' line?"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Start the server for keeps"
step "Paste into Termux (still in ~/inventory-pwa):"
say ""
say "    termux-wake-lock && pm2 start ecosystem.config.cjs && pm2 save"
say ""
step "Then:    pm2 logs inventory-server --nostream --lines 15"
say "Look for the boot line like:   network:  http://192.168.1.23:7300"
ask SERVER_URL "Paste that network: http://...:7300 URL here:"
if command -v curl >/dev/null 2>&1; then
  say ""
  if HEALTH=$(curl -fsS --max-time 5 "$SERVER_URL/api/health" 2>/dev/null); then
    printf '  %s✓ reachable from this Mac — health: %s%s\n' "$GREEN" "$HEALTH" "$RESET"
    PINFO=$(curl -fsS --max-time 5 "$SERVER_URL/api/pair-info" 2>/dev/null || true)
    if [[ -n "$PINFO" ]]; then
      printf '  %s✓ pair-info:%s %s\n' "$GREEN" "$RESET" "$PINFO"
      say "The 'code' in that line is the pairing code — write it down. It expires in 10 minutes; a fresh one can be re-fetched the same way anytime before pairing."
    fi
  else
    warn "This Mac couldn't reach $SERVER_URL just now."
    note "  Check: phone on the same Wi-Fi; router AP/client isolation OFF; URL typed exactly."
    note "  If the URL was mistyped, re-run this wizard later or continue anyway and verify in stage 7."
  fi
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Survive phone reboots (Termux:Boot)"
say "pm2 remembers the server (you did pm2 save), but nothing starts Termux"
say "itself after a phone reboot. The Termux:Boot app fixes that."
open_url "https://f-droid.org/en/packages/com.termux.boot/"
step "Install the Termux:Boot APK from that page, then OPEN IT ONCE (required to register it)."
step "Also give Termux:Boot the same battery Unrestricted treatment as stage 1."
say ""
say "Now paste this one long line into Termux — it installs the boot script:"
say ""
say "    mkdir -p ~/.termux/boot && printf '%s\\n' '#!/data/data/com.termux/files/usr/bin/sh' 'termux-wake-lock' 'sleep 20' 'cd /data/data/com.termux/files/home/inventory-pwa' 'pm2 resurrect' > ~/.termux/boot/inventory.sh && chmod +x ~/.termux/boot/inventory.sh && echo BOOT-SCRIPT-INSTALLED"
say ""
note "It should print BOOT-SCRIPT-INSTALLED on success."
note "If a phone reboot ever leaves the app down anyway: open Termux and run 'pm2 resurrect' — and tell me."
pause "Done — Termux:Boot app opened once and script pasted?"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Pair the shop phone"
say "The server's database is brand-new and empty (that's the plan). Now pair"
say "the phone you'll actually use in the shop:"
step "On that phone, open Chrome and go to:   ${SERVER_URL:-http://<phone-ip>:7300}"
step "Chrome menu (⋮) → 'Add to Home screen' → install it as an app."
step "Open it — it shows the pairing screen."
step "Enter the pairing code from stage 5 (or refetch: in Termux run 'curl localhost:7300/api/pair-info')."
warn "If the app says 'wrong or expired pairing code', the code timed out: in Termux run 'pm2 restart inventory-server', then re-fetch the code and retry."
ask PWA_OPENED "Type Y when the app opened and shows the Home screen:"
if [[ "${PWA_OPENED}" =~ ^[Yy] ]]; then
  printf '  %s✓ The shop is live on your Wi-Fi.%s\n' "$GREEN" "$RESET"
else
  warn "Finish pairing, then re-run this wizard — stage 7 alone re-verifies."
fi
note "Mac demo data (12 mock products) stays on the Mac. Real products are entered in the app itself."

finish
